export const PRODUCTION_TABLE_IDS: string[] = ["btm-receipt", "btm-input-quality", "btm-tally-row", "calibration-run", "silos-stock-row", "wholes-manual-calibration", "cooking-run", "shelling-run", "shelling-machine-sample", "shelling-frequency-sample", "shelling-line-run", "shell-waste-sample", "kernel-quality-sample", "borma-run", "borma-trolley-row", "borma-machine-cycle", "final-output-sample", "peeling-performance", "waste-dispatch", "shell-dispatch", "boiler-consumption", "packing-record", "offloading-bin-report", "wip-stock-report", "issued-to-production"];

/** label -> col for one table. Throws on an unknown label so a typo can't silently no-op a write. */
export function productionColFor(tableId: string, label: string): string {
  const spec = PRODUCTION_FIELD_MAP[tableId];
  if (!spec) throw new Error(`Unknown production table "${tableId}"`);
  const f = spec.fields.find((x) => x.label === label);
  if (!f) throw new Error(`Unknown field "${label}" on production table "${tableId}"`);
  return f.col;
}
